using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class AlbertoMoravia
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "A Roma è avvenuto il contrario di quello che avviene nelle altre capitali: la città si è ingrandita e arricchita; ma è rimasta legata a un’idea del vivere elementare e grossolana. Cinica, scettica, priva di ideali, materiale, ottusa, Roma presenta insomma lo spettacolo sconcertante di una capitale il cui fine principale anzi unico sia quello di vivere alla giornata o meglio di sopravvivere.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Ascesi così, con gli occhi rivolti a terra e il sangue invaso da un fitto benessere, che mi pareva emanare dal luogo: finalmente levai lo sguardo e mi accorsi allora che ero sotto il tempio.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Pier Paolo Pasolini scandalizzava quella borghesia italiana che in quattro secoli ha creato i due più importanti movimenti conservatori d'Europa, cioè la controriforma e il fascismo.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Debbo a Vitaliano Brancati, scrittore da me stimato, la visione d'un tramonto unico: non alla Plaja ma al teatro greco di Siracusa, là dove il mare dei greci è il giusto fondale.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Dietro la spiaggia, oltre un istmo di sabbia, si apre uno dei tanti porticcioli di Procida: un'insenatura rotonda, guardata da due promontori verdi, e in fondo, addossata alla costa, una fila di case. Sono le case per cui Procida è o dovrebbe essere famosa: specie di alveari dai colori teneri, scoperchiati e con le celle in piena luce. Le celle sono le terrazze ad arconi fittamente sovrapposte, con porte verdi in fondo alle terrazze, trecce di paprica rosse penzolanti dagli archi, panni di tutti i colori appesi a mezz'aria. Disposte in cerchio intorno al porto, queste case rosa, gialle, azzurre e bianche sono tutte un po' sbilenche, un po' consunte, un po' diroccate; si pensa che il vento e il mare le abbiano corrose allo stesso modo della costa vulcanica che, a guisa di mensola, si sporge sopra di esse. Ma la mancanza di angoli acuti, quel confondersi delle loro tinte delicate e incantevoli ricordano pure i gelati di questi paesi. Anzi un solo gran gelato di sapori diversi in lenta liquefazione, coi buchi delle terrazze fatti col cucchiaio.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Gli uomini veramente di profondo senso religioso non si scandalizzano mai. Insomma, non credo che Cristo si scandalizzasse mai... Anzi non si è mai scandalizzato. Si scandalizzavano i farisei.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Guardando la mano di Cora che si abbarbica sul vetro nero della bottiglia con le dita lunghe e bianche, e al fiotto schiumoso che a scosse ripetute e successive, erompe nei bicchieri; non posso fare a meno, dico, di pensare che a quello stesso modo, nella casa di Cora, al momento dell'orgasmo, erompe, dopo una lunga preparazione, il seme maschile.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "I giovani del Sessantotto, e quelli che sono venuti dopo, pensano che il mondo vada cambiato, cambiato con la violenza, ma non vogliono sapere perché, e come cambiarlo. Non vogliono conoscerlo, e dunque non vogliono conoscere se stessi.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Il personaggio di Fellini è un erotomane, un sadico, un masochista, un mitomane, un pauroso della vita, un nostalgico del seno materno, un buffone, un mistificatore e un imbroglione. Per qualche aspetto rassomiglia un po' a Leopold Bloom, l'eroe dell'Ulysses di Joyce che Fellini mostra in più punti di aver letto e meditato. Il film è tutto introverso, ossia, in sostanza, è un monologo interiore alternato a radi squarci di realtà. La nevrosi dell'impotenza è illustrata da Fellini con una precisione clinica impressionante e, forse, talvolta persino involontaria. I sogni di Fellini sono sempre sorprendenti e, in senso figurativo, originali; ma nei ricordi traluce un sentimento più delicato e più profondo. Per questo i due episodi dell'infanzia nella rustica casa romagnola e della fanciullezza con il primo incontro con la donna sulla spiaggia di Rimini, sono i più belli del film e tra i più belli di tutta l'opera di Fellini.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Il sentiero pareva essere quello antico, con i gradini a cordonata e le pietre esagonali. A misura che salivo, m'investiva un calore vivificante. Il sole illuminava le rosse colonne fino a tre quarti della loro statura; sui capitelli rotondi era l'ombra dell'alto frontone; e parevano persone ritte nella luce, con la faccia riparata e gli occhi nascosti. Il verso liquido dei neri uccelli cui il luogo silenzioso ed attonito rifiutava la benché minima eco, la folta erbaccia che cresceva sul suolo interno del tempio, la vista sfondata delle montagne lontane tra l'una colonna e l'altra, sul capo il cielo dove un tempo era stato il soffitto; e nonostante questi segni di desolazione e d'abbandono, il nessun senso di rovina, l'accordo insomma del tempio con la natura circostante come se fosse stato costruito per starsene così solo e vuoto e non per riti solenni di un popolo vivente; fu questo contrasto, o meglio questa mancanza di contrasto, questa serenità, ciò che mi fece a prima vista impressione.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Improvvisamente, ad una svolta, ci apparvero i Faraglioni e fui contento di udire Emilia dare in un grido di sorpresa e di ammirazione. Era la prima volta che veniva a Capri e sinora non aveva aperto bocca. Da quell'altezza le due grandi rupi rosse sorprendevano per la loro stranezza, simili, sulla superficie marina, a due aeroliti caduti dal cielo sopra uno specchio. Dissi ad Emilia, esaltato da quella vista, che sui Faraglioni si trovava una razza di lucertole che non esisteva in nessun altro luogo del mondo: azzurre a forza di vivere tra il cielo azzurro e il mare azzurro... La lucertola azzurra che descrivevo annidata tra gli anfratti delle due rupi diventò ad un tratto il simbolo di quello che avremmo potuto diventare noi stessi, se fossimo rimasti a lungo nell'isola: anche noi azzurri dentro il nostro animo dal quale la serenità del soggiorno marino avrebbe gradualmente scacciato la fuliggine dei tristi pensieri della città; azzurri e illuminati dentro di azzurro, come le lucertole, come il mare, come il cielo e come tutto ciò che è chiaro, allegro e puro.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "In maniera paradossale, si potrebbe affermare che appunto perché Dostoevskij nelle Memorie ha il coraggio di parlare di se stesso, proprio per questo, egli attinge a una zona profonda nella quale così se stesso come gli altri non esistono più, annullati da qualche cosa di non individuale e non sociale, ossia da ciò che Dostoevskij chiama il «sottosuolo». L'importanza diciamo così storica delle Memorie dal sottosuolo sta tutta qui. Per la prima volta, riprendendo la metafora del titolo del racconto, Dostoevskij prende una lampada e discende dall'appartamento al primo piano, in cui è sinora vissuto, giù nel sottosuolo della casa. Dostoevskij, per dirla con un famoso verso di Baudelaire, scende nel sottosuolo per «au fond de l'inconnu chercher du nouveau», Dostoevskij troverà nel sottosuolo, cioè nell'«inconnu», il nuovo, cioè «le nouveau» in tale quantità che non ne uscirà più. Tutti i libri dopo le Memorie dal sottosuolo sono stati scritti da quelle latebre tenebrose. E Dostoevskij è morto alla fine nel sottosuolo, senza mai più risalire alle stanze superiori.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "L'uomo vuole sempre sperare. Anche quando è convinto di essere disperato.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "La storia dell'umanità non è che un lungo sbadiglio di noia.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "La sua fine è stata al tempo stesso simile alla sua opera e dissimile da lui. Simile perché egli ne aveva già descritto, nei suoi romanzi e nei suoi film, le modalità squallide e atroci, dissimile perché egli non era uno dei suoi personaggi bensì una figura centrale della nostra cultura, un poeta che aveva segnato un'epoca, un regista geniale, un saggista inesauribile.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Le esperienze che contano sono spesso quelle che non avremmo mai voluto fare, non quelle che decidiamo noi di fare.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Marco Bellocchio parla di cose che conosce benissimo; e quel che più importa, ne parla con una consapevolezza critico-storica rara tra i nostri registi.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Niente ha successo come il successo.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Michelangelo Antonioni, con Professione: reporter ha fatto il suo film più rigoroso ed essenziale.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Non tutti i delitti hanno riflessi sociali. Ma ci sono delitti, invece, in cui tutto è sociale, dall'arma usata all'ambiente fisico, dai caratteri dei protagonisti al loro modo di vita, tutto, perfino il dolore, perfino il peccato, perfino la riparazione, perfino il pentimento.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Pur tenendosi costantemente a un alto livello espressivo, Fellini pare cambiar maniera secondo gli argomenti degli episodi, in una gamma di rappresentazione che va dalla caricatura espressionista fino al più asciutto neorealismo. In generale si nota un'inclinazione alla deformazione caricaturale dovunque il giudizio morale si fa più crudele e più sprezzante, non senza una punta, del resto, di compiacimento e di complicità, come nella scena assai estrosa dell'orgia finale o in quella della festa dei nobili, ammirevole quest'ultima per sagacia descrittiva e ritmo narrativo.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Questa storia di Professione: reporter, ultimo film di Michelangelo Antonioni, a tutta prima fa pensare al Fu Mattia Pascal di Pirandello. Ma Pirandello vuole dimostrare, in maniera sarcastica e paradossale, che l'identità è un mero fatto sociale, cioè che esistiamo in quanto gli altri riconoscono la nostra esistenza; mentre Antonioni sembra pensare giusto il contrario e cioè che esistiamo, sia pure come grumo di dolore, anche e soprattutto fuori della società.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Ricordo un mio viaggio in Israele. A Gerusalemme mi ha fatto da guida il sindaco Teddy Kollek. Mentre percorrevo la Via Crucis, a un certo punto mi ha detto: \"Qui Lui è caduto sotto la Croce!\". Non nascondo che mi è venuto un nodo alla gola. Non riesco ad avere l'idea di un Dio Padre astratto; per me Dio è Gesù. Nessuno ha parlato come Lui: beati quelli che non contano, i poveri, gli infelici...", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Roma ha l'osteria, luogo popolaresco, un po' buio, bonario, con tavole di marmo, boccali di vino, belle insegne rossastre con le scritte: «Vino dei Castelli a tanto il litro».", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Sarebbe stato probabilmente fascista se non fosse morto ancora giovane per una polmonite, che si buscò andando in motocicletta da Siena a Roma.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Si annida nelle cerniere della storia come una ruggine corrosiva.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Sulle sabbie del deserto come sulle acque degli oceani non è possibile soggiornare, mettere radici, abitare, vivere stabilmente. Nel deserto come nell'oceano bisogna continuamente muoversi, e così lasciare che il vento, il vero padrone di queste immensità, cancelli ogni traccia del nostro passaggio, renda di nuovo le distese d'acqua o di sabbia, vergini e inviolate.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Un male incerto provoca inquietudine, perché, in fondo, si spera fino all'ultimo che non sia vero; ma un male sicuro, invece, infonde per qualche tempo una squallida tranquillità.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Si torna così a una misura che è conquistata nella genesi storica dell’opera del giovane artista romano Gian Carlo Riccardi nel recupero pittorico e gestuale per i materiali poveri che caratterizzano l’opera, nei momenti simbolici ed originali del lavoro umano, nella citazione di elementi primordiali generatori di vita e di morte, nella raffigurazione di archetipi che costituiscono il tessuto simbolico dell’uomo, radice stessa della sua storia: una misura che è quindi tramata di passioni, dissidi, reperti, ma che sa ritrovare il “mito”, l’originario simbolico, attraverso l’azione, il gesto dell’artista nella sorgiva forza del desiderio.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Scrittore completo se mai ce ne fu uno, Stendhal era riuscito a rendere poetico, con il suo stile magicamente economico ed estroso di cronachista europeo, tutto ciò che di solito nei romanzi è irriducibilmente ribelle a siffatte trasmutazioni.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Da romanzi brutti si ricavano facilmente bei film perché il romanzo brutto si limita a fornire la materia narrativa, né più né meno di un fatto di cronaca, senza l'impiccio dello stile che non c'è.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Autent-Lara ci ha dato un film lento che da bene l'idea del lento procedere della vita al principio dell'Ottocento. Ma non ha calcolato che se la vita ottocentesca era lenta, Stendhal l'aveva tuttavia descritta con uno stile rapido, talvolta fulmineo nei passaggi e negli scorci, lo stile per eccellenza dell'azione.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Gérard Philipe incarna quasi perfettamente il suo personaggio, con una recitazione sottile ed espressiva. Meglio del solito Danielle Darrieux nella parte di Madame de Renal combattuta tra l'amore e la religione. Antonella Lualdi non è Matilde, ma fa del suo meglio in un personaggio grazioso e semplice.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Anima è quello che appartiene a tutti e a nessuno. Anima è amore. Anima è idea. Anima è libertà. Anima è Dio.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "C'è nei sogni, specialmente in quelli generosi, una qualità impulsiva e compromettente che spesso travolge anche coloro che vorrebbero mantenerli confinati nel limbo innocuo della più inerte fantasia.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Le amicizie non si scelgono a caso ma secondo le passioni che ci dominano.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "L'invidia è come una palla di gomma che più la spingi sotto e più ti torna a galla e non c'è verso di ricacciarla nel fondo.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "La disoccupazione è una cosa per il disoccupato e un'altra per l'occupato. Per il disoccupato è come una malattia di cui deve guarire al più presto, se no muore; per l'occupato è una malattia che gira e lui deve stare attento a non prenderla se non vuole ammalarsi anche lui, ossia diventare, appunto, disoccupato.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Le donne sono come i camaleonti, che dove si posano prendono il colore.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Per una donna i corteggiatori sono come le collane e i braccialetti: ornamenti di cui, se può, preferisce di non disfarsi.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Quando si agisce è segno che ci si aveva pensato prima: l'azione è come il verde di certe piante che spunta appena sopra la terra, ma provate a tirare e vedrete che radici profonde.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Si vede che lo sport rende gli uomini cattivi, facendoli parteggiare per il più forte e odiare il più debole.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Vedi, non c'è coraggio e non c'è paura... ci sono soltanto coscienza e incoscienza... la coscienza è paura, l'incoscienza è coraggio.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Un disgusto opaco l'opprimeva; i suoi pensieri non erano che aridità, deserto; nessuna fede, nessuna speranza alla cui ombra riposare e rinfrescarsi; la falsità e l'abbiezione di cui aveva pieno l'animo egli le vedeva negli altri, sempre, impossibile strapparsi dagli occhi quello sguardo scoraggiato, impuro che si frapponeva tra lui e la vita; un po' di sincerità, si ripeteva riaggrappandosi alla sua vecchia idea fissa, \"un po' di fede… e avrei ucciso Leo… ma ora sarei limpido come una goccia d'acqua.\" Si sentiva soffocare; guardò Lisa, pareva contenta: \"Come vivi?\" avrebbe voluto gridarle: \"sinceramente? con fede? dimmi come riesci a vivere.\" I suoi pensieri erano confusi, contraddittori: \"E ancora\" pensava con un brusco, disperato ritorno alla realtà, \"forse questo dipende soltanto dai miei nervi scossi… forse non è che una questione di denaro o di tempo o di circostanze.\" Ma quanto più si sforzava di ridurre, di semplificare il suo problema, tanto più questo gli appariva difficile, spaventoso. \"È impossibile andare avanti così.\" Avrebbe voluto piangere; la foresta della vita lo circondava da tutte le parti, intricata, cieca; nessun lume splendeva nella lontananza: \"impossibile.\"", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Quando non si è sinceri bisogna fingere, a forza di fingere si finisce per credere; questo è il principio di ogni fede.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Ricordò che a tredici anni era stato un ragazzo timido, un po' femminile, impressionabile, disordinato, fantastico, impetuoso, passionale; adesso, invece, a trenta, era un uomo per nulla timido anzi perfettamente sicuro di sé, del tutto maschile nei gusti e negli atteggiamenti, calmo, ordinato fino all'eccesso, quasi privo di immaginazione, controllato, freddo. Gli pareva, inoltre, di rammentare che c'era stata in lui, allora, una ricchezza tumultuosa e oscura. Adesso, invece, tutto in lui era chiaro sebbene, forse, un poco spento, e la povertà e rigidezza di poche idee e convinzioni avevano preso il posto di quella generosa e confusa abbondanza. Finalmente, era stato incline alla confidenza ed espansivo, talvolta addirittura esuberante. Adesso era chiuso, di umore sempre uguale, senza brio se non proprio triste, silenzioso. Il tratto, però, più distintivo del radicale cambiamento intervenuto in quei diciassette anni, era la scomparsa di una specie di eccesso di vitalità costituito dal ribollire di istinti insoliti e, forse, anche anormali; in luogo del quale, adesso, era subentrata, come pareva, una certa mortificata e grigia normalità.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Che altro poteva essere infatti la verità se non qualche cosa a tutti evidente, da tutti creduta e ritenuta inoppugnabile. Così la catena era ininterrotta, con tutti gli anelli ben saldati dalla sua simpatia, anteriore ad ogni riflessione, alla consapevolezza che questa simpatia era condivisa da altri milioni di persone nella stessa maniera; da questa consapevolezza alla convinzione di essere nel vero; dalla convinzione di essere nel vero all'azione. Perché, come pensò ancora, il possesso della verità non soltanto permetteva l'azione ma anche l'imponeva. Come una conferma da fornire a se stesso e agli altri della propria normalità che tale non era se non veniva, appunto, approfondita, ribadita e dimostrata continuamente.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Marcello non aveva alcuna simpatia per Quadri: lo sapeva antifascista e, nella sua mente l'antifascismo di Quadri, il suo aspetto imbelle, malsano e laido, la sua erudizione, i suoi libri, tutto insomma, gli pareva che contribuisse a formare l'immagine convenzionale e continuamente additata al disprezzo dalla propaganda del partito, dell'intellettuale negativo e impotente.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Ti pare strano, nevvero, che io parli d'azione?. Tra tutti questi libri?. Tu in questo momento pensi: \"ma di che azione va cianciando questo piccolo uomo gobbo, storto, miope, barbuto?\" di' la verità, è questo quello che pensi. I giornaletti del tuo partito ti hanno tante volte descritto l'uomo che non sa e non può agire, l'intellettuale, e ti vien fatto di sorridere con compassione, riconoscendomi in quell'immagine. non è così?", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Noi desideriamo soprattutto che il maggior numero possibile di persone si comprometta e lotta con noi. Andare in prigione per la nostra causa non è che una delle tante maniere di compromettersi e lottare, non certo la sola.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Sentì il bisogno a questo punto di esprimere in parole grezze e sarcastiche la propria situazione e pensò con freddezza: \"Insomma, se il fascismo fa fiasco, se tutte le canaglie, gli incompetenti, e gli imbecilli che stanno a Roma portano la nazione italiana alla rovina, allora io non sono che un misero assassino\".", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Questo è certamente uno dei peggiori effetti della guerra: di rendere insensibili, di indurire il cuore, di ammazzare la pietà.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Questo per dire che ci si abitua a tutto e che la guerra è proprio un'abitudine e che quello che ci cambia non sono i fatti straordinari che avvengono una volta tanto ma proprio quest'abituarsi, che indica, appunto, che accettiamo quello che ci succede e non ci ribelliamo più.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Se fossi religioso, direi che è venuta l'apocalisse, quando appunto si vedranno i cavalli pascolare il grano. Siccome non sono religioso, mi limito a dire che sono venuti i nazisti, il che, forse, è la stessa cosa.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Dunque in quei giorni, una impazienza straordinaria dominava la mia vita. Niente di quello che facevo mi piaceva ossia mi sembrava degno di essere fatto; d'altra parte, non sapevo immaginare niente che potesse piacermi, ossia che potesse occuparmi in maniera durevole.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Il sentimento della noia nasce in me da quello dell'assurdità di una realtà, come ho detto, insufficiente ossia incapace di persuadermi della propria effettiva esistenza.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "In principio, dunque, era la noia, volgarmente chiamata caos. Iddio, annoiatosi della noia, creò la terra, il cielo, l'acqua, gli animali, le piante, Adamo ed Eva; i quali ultimi, annoiandosi a loro volta del paradiso, mangiarono il frutto proibito. Iddio si annoiò di loro e li cacciò dall'Eden.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Sono nato nel 1920, la mia adolescenza passò, dunque, sotto l'insegna nera del fascismo, ossia di un regime politico che aveva eretto a sistema l'incomunicabilità così del dittatore con le masse come dei singoli cittadini fra di loro e con il dittatore.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Soprattutto quando ero bambino, la noia assumeva forme del tutto oscure a me stesso e agli altri, che io ero incapace di spiegare e che gli altri, nel caso di mia madre, attribuivano a disturbi della salute o altri simili cause.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Su tutto questo non so dare altra spiegazione, se non che la contraddizione costituisce il fondo mobile e imprevedibile dell'animo umano.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "L'erotismo di Balestrieri, che io paragonavo spesso ad un vulcano in continua ma tranquilla attività, ebbe, infatti, verso il suo sessantatreesimo anno di età, come una fase parossistica. Le donne che sfilavano nel cortile e andavano a bussare alla porta del vecchio pittore, mi parvero più numerose; inoltre mi accorsi che erano oramai quasi sempre ragazze molto giovani: come tutti i viziosi, Balestrieri, con gli anni, inclinava verso le adolescenti. Ho parlato di una fase parossistica dell'erotismo; sarebbe più esatto dire che si trattò, se mai, di una fissazione, probabilmente inconsapevole, su un tipo solo di donna ad esclusione di tutti gli altri. Insomma, Balestrieri, senza rendersene conto, stava cessando in quel tempo di essere il dongiovanni collezionista che era sempre stato e, per la prima volta, si dedicava o voleva dedicarsi ad una donna sola.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Così, alla fine, il solo risultato veramente sicuro era che avevo imparato ad amare Cecilia, o meglio, ad amare senza più. Ossia speravo di avere imparato. Perché anche per questo aspetto della mia vita, il dubbio non era escluso. E io dovevo aspettare, per esserne del tutto sicuro, che Cecilia fosse tornata dalla sua gita al mare.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Nulla ripugnava maggiormente a Pietro Monatti che una condotta ispirata ai calcoli, agli impulsi e a tutte le altre arbitrarie giustificazioni dell'amor proprio. Oltre che da un disprezzo istintivo per le angustie e per le meschinità dell'egoismo, oltre che da un'ammirazione non meno istintiva per le azioni e i propositi generosi, l'odio per tutte le forme che suole rivestire l'amore di sé e specialmente quelle dell'ambizione, della prepotenza e dell'interesse gli era stato riconfermato da certe sfortunate esperienze della sua prima giovinezza. Per mezzo di quelle esperienze, Pietro era infatti arrivato alla convinzione di possedere una coscienza tanto scomoda e rigorosa da non potere andare fino in fondo né trarre alcun vantaggio da quelle azioni nelle quali si fosse lasciato guidare dal solo tornaconto; e a differenza della maggior parte degli uomini, i quali – egoisti per natura – non sanno comportarsi generosamente che per forza di calcolo e di volontà, di essere invece naturalmente portato al disinteresse, alla lealtà, all'altruismo, e a tutte le altre virtù umane. Questa scoperta era stata la conclusione di una lunga crisi, e, fatto anche più notevole, il principio di una serie di fortune. Giacché messosi d'accordo con se stesso e riordinata la propria vita secondo i concetti che gli parevan più rispondenti alla vera conformazione del suo carattere, Pietro aveva finalmente conosciuto quella tranquillità dell'animo senza la quale non sono possibili gli sviluppi del lavoro e i fruttuosi rapporti col mondo.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Gli altri si arrabattano con la furbizia, coi calcoli e con gli inganni, e alla fine, machiavellici come sono, si ritrovano tuttavia con un pugno di mosche. A me invece, che agisco sempre con sincerità e seguendo i miei migliori istinti, che odio l'inganno e il calcolo, a me, l'ingenuo, l'uomo che non sa vivere, tutto va di bene in meglio. Loro cercano di farsi largo a furia di imbrogli, e di malafede e non riescono ad uscire dal loro stato mediocre. Io invece, neppure mi curo di farmi avanti, bado soltanto a procurarmi degli amici, a creare dei legami di affetto, ad essere in buoni e veri rapporti con ogni persona che conosco, e mi ritrovo poi alla fine avvantaggiato, e quegli amici, quei legami d'affetto, quei rapporti, si rivelano come i migliori strumenti della mia fortuna. Tanto è vero che la migliore furbizia è non essere furbi.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Gli scrupoli portano lontano. Guarda gli inglesi, per esempio, che hanno conquistato mezzo mondo: sono pieni di scrupoli.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "\"È possibile vivere nella disperazione e non desiderare la morte?\" Immaginavo, per gioco, di leggere questa domanda in una specie di insegna che un grandissimo pipistrello dalle ali spiegate, simile a quello che si vede nella stampa di Dürer ''Melencolia'', teneva sospesa tra le unghie al di sopra del mare, mentre il vaporetto si avvicinava rapidamente all'isola di Capri. Forse era l'atmosfera del temporale imminente a suggerirmi l'analogia con la stampa del pittore tedesco.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Nei primi giorni d'estate, Agostino e sua madre uscivano tutte le mattine sul mare in pattino. Le prime volte, la madre aveva fatto venire anche un marinaio, ma Agostino aveva mostrato per così chiari segni che la presenza dell'uomo l'annoiava, che da allora i remi furono affidati a lui. Egli remava con un piacere profondo su quel mare calmo e diafano del primo mattino e la madre, seduta di fronte a lui, gli discorreva pianamente, lieta e serena come il mare e il cielo, proprio come se lui fosse stato un uomo e non un ragazzo di tredici anni.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Durante il volo ho aperto a caso il volume delle poesie di Guillaume Apollinaire; i miei occhi sono caduti su un verso: \"Eccoti a Roma seduto sopra un nespolo del Giappone\" e ho preso a fantasticare: perché un nespolo del Giappone? Che aveva a che fare con Roma quell'albero asiatico? E poiché Apollinaire era il mio modello e la mia guida, che cosa avrebbe significato nella mia vita, una volta arrivato a Roma, il nespolo del Giappone?", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Intrigante! Subdolo! Fedifrago! Vile! Ecco come mantiene le promesse! Ecco come sta ai patti! Dormo, faccio una quantità di sogni indifferenti che ora non ricordo, e, alla fine, sogno di essere in uno studio cinematografico, grandissimo, immerso nella penombra. In un angolo, sul carrello, sta la macchina da presa incappucciata in un panno nero. So di certo che sto girando, finalmente!, il \"mio\" film. Quale film? Chi è il produttore? Chi sono gli attori? Non lo so. So soltanto che è il \"mio\" film. Il film al quale penso da quindici anni. Il film dal quale dipende tutta la mia vita.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Prima di tutto voglio parlare di mia moglie. Amare, oltre a molte altre cose, vuol dire trarre diletto dal guardare e osservare la persona amata. E non soltanto trarre questo diletto dalla contemplazione delle sue bellezze ma anche da quella delle sue bruttezze, poche o molte che siano. Fin dai primi giorni di matrimonio, io trovai un inestimabile piacere nel guardare Leda (così ella si chiama) e nello studiare il viso e la persona fin nei minimi gesti e nelle più fuggevoli espressioni.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Ore sei e trenta. Dormo poco, non più di sei ore per notte e, appena mi sveglio, dedico cinque, dieci minuti a quella rara occupazione che va sotto il nome di pensiero. A che cosa penso? A dirlo così può persino parere ridicolo: alla fine del mondo. Non so quando e in che modo è cominciata questa abitudine; forse non tanto tempo fa, in seguito alla lettura di un libro che per caso ho trovato sulla scrivania di mio padre che è professore di fisica all'università, un libro, fra i tanti, sulla guerra nucleare. Oppure sarà stato un altro motivo venuto da chissà dove e poi scomparso dalla mia memoria, come scompare il seme una volta che la pianta è cresciuta.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Passate le vacanze nel solito luogo al mare, Luca tornò in città con la sensazione che non stava bene e si sarebbe presto ammalato. Egli era cresciuto in maniera anormale negli ultimi tempi e a quindici anni aveva già la statura di un uomo adulto. Ma le spalle erano rimaste strette e gracili; e nel viso bianco, gli occhi troppo intensi parevano divorare le guance smunte e la fronte pallida. Fosse stato consapevole di questa sua gracilità e dei pericoli che comportava, si sarebbe forse raccomandato ai genitori affinché gli facessero sospendere gli studi...", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "A sedici anni ero una vera bellezza. Avevo il viso di un ovale perfetto, stretto alle tempie e un po' largo in basso, gli occhi lunghi, grandi e dolci, il naso dritto in una sola linea con la fronte, la bocca grande, con le labbra belle, rosse e carnose e, se ridevo, mostravo denti regolari e molto bianchi. La mamma diceva che sembravo una madonna.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Hanno affittato per l'estate una villa situata sulle dune, a poca distanza da un borgo, su un litorale famoso per i suoi stabilimenti balneari. A nord e a sud del borgo, la riviera continua per centinaia di chilometri, alternando centri di villeggiatura con alberghi, ristoranti, bar, balere a tratti ancora disabitati dell'originaria macchia mediterranea.", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "La solitudine è finita a partire dal momento che Lola Lopez, trovatella di origine probabilmente peruviana, lascia il convento dove, anno dopo anno, ha fatto di tutto, dalla sguattera all'infermiera, ed è andata a vivere per conto suo in un quartierino di una sola stanza, in cima ad una casetta di Trastevere. Al convento era sola benché in compagnia; qui nella sua monocamera è in compagnia benché sola. La causa di questa contraddizione è un cucciolo che le buone suore le hanno regalato, nato da una cagna che ha messo al mondo tutta una cucciolata in fondo al giardino del convento. Lola lo ha chiamato Palocco in ricordo del convento che si trova a Casal Palocco...", Author = "Alberto Moravia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alberto_Moravia", Text = "Gita nella campagna inglese Londra, novembre L'automobile correva per una straducola in discesa del tutto buia, profondamente incastrata tra due ripe alte e nere; ogni volta che il raggio dei fanali batteva su queste ripe vedevo intrighi di bianchicci e impressionanti di grossissime radici che mi facevano immaginare tronchi adeguati e non meno straordinari. Fu questa la prima impressione che ebbi della campagna inglese, non dissimile da quella di un viaggiatore addormentato, che svegliato ad un tratto da una brusca fermata in piena campagna, si affacci e intravveda illuminati dalle luci del treno oggetti di un aspetto inconsueto che gli ricordano ad un tratto di essere in un paese sconosciuto, il cui vero aspetto non gli sarà rivelato se non al sorgere del sole.", Author = "Alberto Moravia" },
        };
    }
}